// Rows are ordered by detected_date DESC, so the first row seen per account holds its latest signal.
const aggregatedData = {};

for (const item of $input.all()) {
  const row = item.json;

  if (!aggregatedData[row.account_id]) {
    aggregatedData[row.account_id] = {
      account: {
        account_id: row.account_id,
        account_name: row.account_name,
        domain: row.domain,
        industry: row.industry,
        company_size: row.company_size,
        geography: row.geography,
        growth_stage: row.growth_stage,
        tech_stack: row.tech_stack,
        status: row.status
      },
      signal: {
        signal_id: row.signal_id,
        signal_type: row.signal_type,
        detected_date: row.detected_date,
        evidence_description: row.evidence_description,
        evidence_url: row.evidence_url,
        signal_strength: row.signal_strength
      },
      contacts: []
    };
  }

  const exists = aggregatedData[row.account_id].contacts.find(c => c.contact_id === row.contact_id);
  if (!exists && row.contact_id) {
    aggregatedData[row.account_id].contacts.push({
      contact_id: row.contact_id,
      contact_name: row.contact_name,
      job_role: row.job_role
    });
  }
}

return Object.values(aggregatedData).map(data => ({ json: data }));

return $input.all().map(item => {
  const cleaned = String(item.json.text).replace(/```json|```/g, '').trim();
  const p = JSON.parse(cleaned);

  const fit = parseInt(p.fit_score, 10) || 0;
  const timing = parseInt(p.timing_score, 10) || 0;
  const total = fit + timing;

  // Recompute tier in code so the routing never depends on the LLM's arithmetic
  let tier = 'C';
  if (total >= 150 && fit >= 70) tier = 'A';
  else if (total >= 100) tier = 'B';

  return {
    json: {
      ...p,
      fit_score: fit,
      timing_score: timing,
      total_score: total,
      tier
    }
  };
});

return $input.all().map(item => {
  let p = {};
  try {
    p = JSON.parse(String(item.json.text).replace(/```json|```/g, '').trim());
  } catch (e) {
    p = {};
  }
  const facts = Array.isArray(p.research_brief) ? p.research_brief : [];
  return {
    json: {
      account_id: p.account_id,
      signal_id: p.signal_id,
      fact_1: facts[0] ?? null,
      fact_2: facts[1] ?? null,
      fact_3: facts[2] ?? null
    }
  };
});
